INSERT INTO `empreendimento` VALUES (4,'Residencial Aurora Pinheiros','Lançamento exclusivo com design biofílico, lazer no rooftop e localização privilegiada próxima ao metrô.',85,2,'LANCAMENTO',4),(5,'Skyline Moema','Apartamentos compactos de luxo, ideais para investimento ou moradia moderna no coração de Moema.',42,3,'LANCAMENTO',5),(6,'Itaim Premium Living','O auge da sofisticação com pé direito duplo e vista definitiva para o skyline da cidade.',150,3,'LANCAMENTO',6),(7,'Brooklin Horizon','Conceito aberto e moderno, focado em mobilidade urbana e coworking integrado ao condomínio.',55,2,'LANCAMENTO',7),(8,'Vila Mariana Green House','Lançamento sustentável com horta comunitária e reaproveitamento de água, ao lado do Parque Ibirapuera.',110,3,'LANCAMENTO',8),(9,'Urban Perdizes','Obra em estágio avançado. Apartamento com excelente distribuição interna em bairro tradicional.',92,3,'EM_OBRAS',9),(10,'Metrópole Tatuapé','Em obras aceleradas. Complexo moderno com integração total ao shopping e metrô.',68,2,'EM_OBRAS',10),(11,'Belém Garden Residence','Construção iniciada. Apartamentos com varanda gourmet e lazer completo para crianças.',75.5,3,'EM_OBRAS',11),(12,'Morumbi View Tower','Em obras. Vista panorâmica para a ponte estaiada com acabamento em mármore importado.',210,4,'EM_OBRAS',12),(13,'Santana Sky Home','Fase de acabamento. Estrutura de lazer completa no último andar com piscina infinita.',125,3,'EM_OBRAS',13),(14,'Classic Higienópolis','Totalmente reformado em estilo retro-contemporâneo. Pronto para morar em rua arborizada.',185,4,'DISPONIVEL',14),(15,'Modern Jardins Loft','Lindo loft mobiliado com móveis planejados de alto padrão, ar condicionado e automação.',60,1,'DISPONIVEL',15),(16,'Life Butantã','Excelente oportunidade para jovens profissionais. Próximo à USP com lazer completo.',50.5,2,'DISPONIVEL',16),(17,'Sacomã Residence Club','Apartamento ensolarado, andar alto com vista para o parque e 2 vagas fixas de garagem.',72,3,'DISPONIVEL',17),(18,'Conquista Lapa','Imóvel pronto, recém pintado e com armários embutidos em todos os cômodos.',88,3,'DISPONIVEL',18);
